#include <stdio.h>

#define MAX(a,b) ((a) > (b) ? (a) : (b))

#define MAX_SIZE 10000

int main() {
    int heights[MAX_SIZE];
    int heights_size = 0;

    while(scanf("%d", &heights[heights_size++])) {
        if(getchar() != ',') break;
    }

    int l = 0;
    int r = heights_size - 1;

    long maxArea = 0;

    while(l < r) {
        long x = r - l;
        long y = heights[l] < heights[r] ? heights[l++] : heights[r--];
        maxArea = MAX(maxArea, x * y);
    }

    printf("%ld\n", maxArea);

    return 0;
}
